// Product API service tests (generated by engineering-platform frontend-product-reference asset)
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { http } from '../src/api/request';
import { productApi } from '../src/api/product';
import type { Product } from '../src/types/product';

const product: Product = {
  id: '1', code: 'PRD-001', name: 'P-HQ-1', status: 'ENABLED', category: 'ELECTRONIC',
  departmentId: '1', createdBy: '1', createdAt: '2026-08-15T00:00:00', updatedAt: '2026-08-15T00:00:00',
};

describe('productApi', () => {
  beforeEach(() => {
    vi.restoreAllMocks();
  });

  it('page builds query string with filters', async () => {
    const spy = vi.spyOn(http, 'get').mockResolvedValue({ items: [product], total: 1, page: 1, size: 20 });
    await productApi.page({ page: 1, size: 20, keyword: 'PRD', status: 'ENABLED', category: 'ELECTRONIC' });
    const [path] = spy.mock.calls[0] as [string];
    expect(path).toContain('page=1');
    expect(path).toContain('keyword=PRD');
    expect(path).toContain('status=ENABLED');
    expect(path).toContain('category=ELECTRONIC');
  });

  it('page omits empty filters', async () => {
    const spy = vi.spyOn(http, 'get').mockResolvedValue({ items: [], total: 0, page: 1, size: 20 });
    await productApi.page({ page: 1, size: 20 });
    const [path] = spy.mock.calls[0] as [string];
    expect(path).not.toContain('keyword=');
    expect(path).not.toContain('status=');
  });

  it('detail/create/update/disable route to the right paths', async () => {
    const get = vi.spyOn(http, 'get').mockResolvedValue(product);
    const post = vi.spyOn(http, 'post').mockResolvedValue(product);
    const put = vi.spyOn(http, 'put').mockResolvedValue(product);

    await productApi.detail('5');
    expect((get.mock.calls[0] as [string])[0]).toBe('/products/5');

    await productApi.create({ code: 'X', name: 'Y', status: 'ENABLED', category: null });
    expect((post.mock.calls[0] as [string])[0]).toBe('/products');

    await productApi.update('5', { code: 'X', name: 'Y', status: 'DISABLED', category: null });
    expect((put.mock.calls[0] as [string])[0]).toBe('/products/5');

    await productApi.disable('5');
    expect((post.mock.calls[1] as [string])[0]).toBe('/products/5/disable');
  });
});
